import java.util.*;

public class Main {
    static Perintah urai(String baris) {
        String[] d = baris.strip().split(" ");
        return switch (d[0]) {
            case "tambah" -> new Tambah(d[1], Integer.parseInt(d[2]));
            case "hapus" -> new Hapus(d[1]);
            case "tunai" -> new Bayar(new Tunai(Integer.parseInt(d[1])));
            case "qris" -> new Bayar(new Qris(d[1]));
            default -> throw new IllegalArgumentException("perintah tidak dikenal: " + d[0]);
        };
    }

    public static void main(String[] args) throws Exception {
        Kasir kasir = new Kasir(List.of(
                new Produk("K01", "Kopi", 18000),
                new Produk("T01", "Teh", 8000),
                new Produk("R01", "Roti", 12000)));
        System.out.println(kasir.jalankan(new Tambah("K01", 1)));
        System.out.println(kasir.jalankan(new Bayar(new Qris("QR-9"))));
    }
}

record Produk(String kode, String nama, int harga) {}

sealed interface Perintah permits Tambah, Hapus, Bayar {}

record Tambah(String kode, int jumlah) implements Perintah {}

record Hapus(String kode) implements Perintah {}

record Bayar(Pembayaran cara) implements Perintah {}

sealed interface Pembayaran permits Tunai, Qris {}

record Tunai(int dibayar) implements Pembayaran {}

record Qris(String id) implements Pembayaran {}

class Kasir {
    private final Map<String, Produk> katalog;
    private final SequencedMap<String, Integer> keranjang = new LinkedHashMap<>();

    Kasir(List<Produk> produk) {
        katalog = new HashMap<>();
        for (Produk p : produk) {
            katalog.put(p.kode(), p);
        }
    }

    String jalankan(Perintah perintah) {
        return switch (perintah) {
            case Tambah(var kode, var jumlah) when !katalog.containsKey(kode) -> "Produk " + kode + " tidak ada";
            case Tambah(var kode, var jumlah) -> {
                keranjang.merge(kode, jumlah, Integer::sum);
                yield "+ " + katalog.get(kode).nama() + " x" + jumlah;
            }
            case Hapus(var kode) -> keranjang.remove(kode) != null ? "- " + kode : "Tidak ada di keranjang: " + kode;
            case Bayar(var cara) -> bayar(cara);
        };
    }

    int total() {
        int t = 0;
        for (var e : keranjang.entrySet()) {
            t += katalog.get(e.getKey()).harga() * e.getValue();
        }
        return t;
    }

    private String bayar(Pembayaran cara) {
        int total = total();
        return switch (cara) {
            case Tunai(var dibayar) when dibayar < total -> "Uang kurang " + (total - dibayar);
            case Tunai(var dibayar) -> "Lunas tunai " + total + ", kembali " + (dibayar - total);
            case Qris(var id) -> "Lunas QRIS " + total + " (" + id + ")";
        };
    }
}

